def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    dangerous_prev = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) >= bid * 0.8:
                    dangerous_prev.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    slots = supply / WATER_REQ
    tight = slots < 2.0
    very_tight = slots < 1.5

    high_prev = max(prev_bids) if prev_bids else 0.0
    threat_prev = max(dangerous_prev) if dangerous_prev else high_prev

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 1

    if very_tight:
        urgency += 2
    elif tight:
        urgency += 1

    if day >= 8:
        urgency += 1

    if urgency <= 1:
        bid = 16.0 if not tight else 24.0
        if high_prev >= 100 and hp > 4:
            bid = 12.0
    elif urgency == 2:
        bid = max(28.0, min(45.0, threat_prev * 0.55))
    elif urgency == 3:
        bid = max(48.0, min(72.0, threat_prev * 0.78 + 2.0))
    elif urgency == 4:
        bid = max(68.0, min(96.0, threat_prev * 0.9 + 3.0))
    else:
        bid = max(88.0, min(118.0, threat_prev + 2.5))

    for agent_id, opp in opponents_status.items():
        if not opp.get('alive'):
            continue
        prev = opp.get('previous_trace', {})
        obid = prev.get('bid') if prev else None
        obudget = opp.get('budget', 0)
        if obid is None:
            continue
        if obid >= 95 and obudget < 25 and hp > 4 and no_water == 0:
            bid = min(bid, 22.0)
        if obid <= 60 and obudget > 60 and (urgency >= 3 or tight):
            bid = max(bid, min(85.0, obid + 6.0))

    reserve = 0.0
    if hp > 3 and day < 9:
        reserve = 12.0
    max_affordable = max(0.0, budget - reserve)
    if urgency >= 4:
        max_affordable = budget

    bid = min(bid, max_affordable)

    if hp <= 2 or no_water >= 2:
        bid = max(bid, min(budget, max(90.0, threat_prev + 3.0)))

    if budget < 20:
        bid = min(bid, budget)

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    MY_WATER_REQ = 9
    MY_DAILY_SALARY = 90
    EPISODE_DAYS = 10

    days_remaining = EPISODE_DAYS - day_context['day']

    if my_status['hp'] <= 2:
        my_current_bid = MY_DAILY_SALARY * 1.3 # Critical HP, bid very aggressively
    elif my_status['hp'] <= 5:
        my_current_bid = MY_DAILY_SALARY * 1.1 # Low HP, prioritize water
    else:
        my_current_bid = MY_DAILY_SALARY * 0.95 # Healthy HP, be competitive but conserve

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if my_status['hp'] <= 5:
            my_current_bid = max(my_current_bid, highest_prev_bid * 1.05) # Aggressively beat if HP is low
        else:
            my_current_bid = max(my_current_bid, highest_prev_bid + 1.0) # Slightly beat if HP is good

    if days_remaining <= 3 and my_status['budget'] > my_current_bid:
        my_current_bid *= 1.1 # Increase bid for end-game to secure water

    final_bid = min(my_status['budget'], my_current_bid)
    final_bid = max(1.0, final_bid)

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Collect previous bids from alive opponents
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])

    # Base bid on HP and opponent behavior
    if hp <= 2:
        # Critical: need water
        bid = min(budget, DAILY_SALARY * 0.95)
    elif hp <= 4:
        # Moderate need, consider opponent aggression
        if prev_bids and max(prev_bids) > DAILY_SALARY * 1.2:
            # Opponents were very aggressive, let them waste
            bid = min(budget, DAILY_SALARY * 0.3)
        else:
            bid = min(budget, DAILY_SALARY * 0.6)
    else:
        # Healthy, can be conservative
        if prev_bids and max(prev_bids) > DAILY_SALARY * 1.1:
            bid = min(budget, DAILY_SALARY * 0.2)
        else:
            # Adjust for supply
            if supply < 18:
                bid = min(budget, DAILY_SALARY * 0.5)
            else:
                bid = min(budget, DAILY_SALARY * 0.3)

    # Ensure bid is within budget and non-negative
    bid = max(0, min(bid, budget))
    # Round to 2 decimals
    bid = round(bid, 2)
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from immediate previous_trace only
    prev_bids = []
    prev_hp = []
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid', 0.0)))
                prev_hp.append(float(prev.get('hp_after', opp.get('hp', 0.0))))
            except Exception:
                pass

    # Base target from observed meta: Alex/Bob ~105 average; use max of their yesterday bids as pressure proxy
    target = 0.0
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If someone already paid high yesterday, we slightly undercut to win at lower price.
        # Otherwise, we bid around the typical aggressive level.
        if highest_prev_bid >= DAILY_SALARY * 0.75:
            target = highest_prev_bid * 0.92
        else:
            target = max(90.0, min(115.0, highest_prev_bid + 2.0))
    else:
        target = 105.0

    # Survival/budget risk controls
    # If we are already in danger (low hp or many no-water days), bid harder to secure water.
    danger = (my_hp <= 2.5) or (my_no_water_days >= 2)

    # Supply affects urgency: lower supply means fewer units; bid slightly higher when supply is tight.
    supply_tight = supply <= (MIN_SUPPLY + 2.0)

    if danger:
        target *= 1.12
    if supply_tight:
        target *= 1.06

    # Don't spend beyond what keeps us alive across remaining days (rough heuristic)
    # episode_days not provided here; use a conservative cap based on budget.
    spend_cap = max(0.0, my_budget * (0.35 if not danger else 0.55))

    bid = min(my_budget, target, spend_cap)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    # If we have very low budget, still try a minimal bid to avoid total collapse.
    if my_budget <= 5.0:
        bid = min(my_budget, 4.0)

    return float(bid)
